insert into public.book_quiz (book_key, book_title, tier, question, options, answer, explanation) values
('ready player two', 'Ready Player Two', 50, 'Que découvre Wade, peu après sa victoire, dans les coffres d''Halliday ?', '["Le code source complet de l''OASIS","Le testament secret de James Halliday","Une nouvelle technologie d''immersion, le casque ONI","Un second œuf de Pâques caché dans l''OASIS"]'::jsonb, 2, 'Wade trouve une technologie capable de changer à nouveau le monde, l''ONI, une interface cerveau-machine. Elle s''accompagne d''une nouvelle quête d''Halliday et d''un adversaire dangereux.'),
('ne t arrete pas', 'Ne t''arrête pas', 50, 'Dans quel état Noa se retrouve-t-elle au début du roman ?', '["À l''hôpital, entourée de sa famille","Perdue en forêt, un sac de billets à la main","Sur une table d''opération, une cicatrice sur la poitrine","Enfermée dans un laboratoire, les mains attachées"]'::jsonb, 2, 'Noa se réveille sans savoir où elle est ni ce qui lui est arrivé, avec une cicatrice en travers de la poitrine. Elle s''enfuit alors que des tueurs sont à ses trousses.'),
('la loi du talion', 'La loi du talion', 50, 'Quel est le métier d''Élisabeth, qui disparaît au début du roman ?', '["Avocate à Paris","Institutrice à Marseille","Infirmière à Lyon","Journaliste à Bordeaux"]'::jsonb, 2, 'Élisabeth a 29 ans, travaille comme infirmière à Lyon et porte un lourd secret. Ses proches se lancent à sa recherche après sa disparition.'),
('il suffit parfois d un signe', 'Il suffit parfois d''un signe', 50, 'Quels phénomènes l''autrice présente-t-elle comme des signes ?', '["Seulement les événements spectaculaires","Les coïncidences de dates et de chiffres","Uniquement les prédictions des astrologues","Les rêves, les intuitions et les synchronicités"]'::jsonb, 3, 'Anne Tuffigo parle de prémonitions, de songes, de synchronicités, de déjà-vu et d''intuitions, que l''on reçoit au quotidien sans forcément y prêter attention.'),
('il suffit parfois d un signe', 'Il suffit parfois d''un signe', 100, 'Que permet, selon le livre, de savoir décrypter ces signes ?', '["Gagner en endurance physique","Réussir tous ses examens","Améliorer sa mémoire des dates","Mieux se connaître soi-même"]'::jsonb, 3, 'Le livre affirme que prendre conscience de ces signes et apprendre à les décrypter ouvre les portes d''une formidable connaissance de soi et permet de renouer avec l''essentiel.'),
('l elegance de la manipulation', 'L''élégance de la manipulation', 100, 'Que propose Marwan Mery quand les arguments et la pression échouent ?', '["Éviter définitivement le sujet","Faire changer d''avis sans heurter l''autre","Imposer sa décision par la hiérarchie","Répéter ses arguments plus fort"]'::jsonb, 1, 'Le livre explique comment influencer et convaincre sans conflit, y compris dans des situations difficiles comme détourner un enfant de son écran.'),
('le 3e reich des origines a la chute tome 1', 'Le 3e Reich des origines à la chute tome 1', 50, 'Quelle période couvre ce premier volume ?', '["Les années 1871 à 1914","Les années 1920 à 1939","Les années 1945 à 1960","Les années 1914 à 1918"]'::jsonb, 1, 'Le premier volume suit l''histoire de l''Allemagne dans son contexte européen des années 1920 à 1939. Le second couvre 1939-1945.'),
('le 3e reich des origines a la chute tome 1', 'Le 3e Reich des origines à la chute tome 1', 100, 'Quelle distinction l''ouvrage de Shirer a-t-il reçue aux États-Unis en 1961 ?', '["Le prix Renaudot","Le prix Nobel de littérature","Le National Book Award de non-fiction","Le prix Médicis"]'::jsonb, 2, 'Publié en 1960, l''ouvrage reçoit le National Book Award de non-fiction en 1961 et s''impose comme une référence sur le IIIe Reich.')
